-- Detailed, paraphrased garment introductions with a scoped source for each section.
-- Update the existing three categories; preserve identities and V11 original provenance.
UPDATE cultural_knowledge SET title='Nguồn gốc và tiến trình lịch sử',content='Áo dài hiện đại kế thừa áo ngũ thân, gắn với thay đổi y phục ở Đàng Trong thời Nguyễn Phúc Khoát. Thập niên 1930, Nguyễn Cát Tường (Le Mur) phát triển phom hai tà ôm dáng; về sau, cổ áo, tay và chiều dài tiếp tục biến đổi.',source_name='Cục Du lịch Quốc gia Việt Nam – Vietnam Tourism – All about ao dai: Vietnam''s national dress',source_url='https://vietnam.travel/things-to-do/ao-dai-vietnam' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_DAI') AND category='ORIGIN';
UPDATE cultural_knowledge SET title='Cấu trúc và dấu hiệu nhận diện',content='Dáng áo dài quen thuộc có thân trên vừa người, hai tà rủ và mặc cùng quần. Áo đương đại có thể dùng cổ thuyền, tay ngắn hoặc tà ngắn. Những thay đổi ấy tạo nhiều lựa chọn, nên cần phân biệt thiết kế hiện đại với phom ngũ thân trước đó.',source_name='Cục Du lịch Quốc gia Việt Nam – Vietnam Tourism – All about ao dai: Vietnam''s national dress',source_url='https://vietnam.travel/things-to-do/ao-dai-vietnam' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_DAI') AND category='CHARACTERISTICS';
UPDATE cultural_knowledge SET title='Trang phục kể chuyện văn hóa',content='Áo dài còn là nơi chuyển tải ký ức và hình ảnh đất nước. Trong triển lãm tại Bảo tàng Phụ nữ Việt Nam năm 2022, các nhà thiết kế đưa cảm hứng từ Hạ Long, Phong Nha và thổ cẩm lên áo, kết nối thời trang với di sản địa phương.',source_name='Bảo tàng Phụ nữ Việt Nam – Bảo tàng Phụ nữ Việt Nam nơi lắng đọng giá trị di sản',source_url='https://baotangphunu.org.vn/bao-tang-phu-nu-viet-nam-noi-lang-dong-gia-tri-di-san/' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_DAI') AND category='MEANING';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'WEARING','Cách mặc và lựa chọn màu sắc','Quần đi cùng giúp hoàn chỉnh bộ áo dài. Màu trắng thường gợi hình ảnh nữ sinh; đỏ hay xuất hiện dịp Tết hoặc cưới hỏi. Đây là những liên hệ thường gặp trong đời sống, không phải quy định bắt buộc cho mọi người mặc.','Cục Du lịch Quốc gia Việt Nam – Vietnam Tourism – All about ao dai: Vietnam''s national dress','https://vietnam.travel/things-to-do/ao-dai-vietnam' FROM outfits WHERE code='AO_DAI';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'CONTEXT','Áo dài trong đời sống hôm nay','Áo dài được chọn khi thăm gia đình dịp Tết, dự lễ cưới hoặc chụp ảnh. Trang phục của cô dâu, chú rể thường cầu kỳ hơn áo của khách. Sự đa dạng về kiểu dáng giúp áo dài hiện diện trong cả dịp trang trọng và trải nghiệm du lịch.','Cục Du lịch Quốc gia Việt Nam – Vietnam Tourism – All about ao dai: Vietnam''s national dress','https://vietnam.travel/things-to-do/ao-dai-vietnam' FROM outfits WHERE code='AO_DAI';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'PRESERVATION','Bảo tồn qua nghề may và bảo tàng','Năm 2022, Bảo tàng Phụ nữ Việt Nam tiếp nhận 200 bộ áo dài từ các nhà thiết kế để lưu giữ và phát huy giá trị. Các bộ sưu tập sử dụng lụa, vải gai và hình ảnh di sản cho thấy bảo tồn cũng có thể đi cùng sáng tạo.

Khi tìm hiểu một mẫu áo, nên chú ý chất liệu, tác giả và ý tưởng hoa văn thay vì chỉ nhìn màu sắc.','Bảo tàng Phụ nữ Việt Nam – Bảo tàng Phụ nữ Việt Nam nơi lắng đọng giá trị di sản','https://baotangphunu.org.vn/bao-tang-phu-nu-viet-nam-noi-lang-dong-gia-tri-di-san/' FROM outfits WHERE code='AO_DAI';
UPDATE cultural_knowledge SET title='Áo tứ thân và phụ nữ Bắc Bộ',content='Nghiên cứu của Trịnh Bách mô tả áo tứ thân nâu sồng cùng yếm, váy như trang phục từng quen thuộc với phụ nữ nông thôn Bắc Bộ. Tư liệu phân biệt dạng mặc trong sinh hoạt với những mẫu nhiều màu được cải biên cho trình diễn sau này.',source_name='Hội LHPN tỉnh Khánh Hòa – nghiên cứu của Trịnh Bách – Nguồn gốc của Áo dài Việt Nam (phần 1)',source_url='https://hlhpn.khanhhoa.gov.vn/article/tin-tuc-su-kien/nguon-goc-cua-ao-dai-viet-nam-phan-1.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_TU_THAN') AND category='ORIGIN';
UPDATE cultural_knowledge SET title='Bốn thân áo và kiểu mở trước',content='Tên gọi tứ thân chỉ kết cấu bốn thân. Dạng được nghiên cứu có hai vạt trước mở giữa, không cài khuy; tay áo hẹp và dài tới cổ tay. Vạt có thể buông hoặc thắt, tạo hình dáng khác với áo ngũ thân cài sang một bên.',source_name='Hội LHPN tỉnh Khánh Hòa – nghiên cứu của Trịnh Bách – Nguồn gốc của Áo dài Việt Nam (phần 1)',source_url='https://hlhpn.khanhhoa.gov.vn/article/tin-tuc-su-kien/nguon-goc-cua-ao-dai-viet-nam-phan-1.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_TU_THAN') AND category='CHARACTERISTICS';
UPDATE cultural_knowledge SET title='Liên hệ với văn hóa Kinh Bắc',content='Trong sinh hoạt Quan họ, trang phục góp phần tạo nên hình ảnh liền chị bên cạnh lời ca giao duyên. Cục Di sản văn hóa mô tả áo mớ ba, mớ bảy và nón thúng quai thao. Khi tìm hiểu áo tứ thân, đây là một bối cảnh văn hóa liên quan, không phải mô tả duy nhất cho mọi mẫu áo.',source_name='Cục Di sản văn hóa – Dân ca Quan họ Bắc Ninh',source_url='https://dsvh.gov.vn/dan-ca-quan-ho-bac-ninh-482' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_TU_THAN') AND category='MEANING';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'WEARING','Yếm, váy và dây lưng vải','Cách mặc được ghi nhận kết hợp áo ngoài với yếm và váy. Có thể khép các vạt, dùng dây lưng vải giữ áo, hoặc thắt vạt phía trước. Đối chiếu ảnh tư liệu giúp hiểu cách buông, thắt và phối lớp thay vì coi mọi bản sân khấu là nguyên mẫu.','Hội LHPN tỉnh Khánh Hòa – nghiên cứu của Trịnh Bách – Nguồn gốc của Áo dài Việt Nam (phần 1)','https://hlhpn.khanhhoa.gov.vn/article/tin-tuc-su-kien/nguon-goc-cua-ao-dai-viet-nam-phan-1.html' FROM outfits WHERE code='AO_TU_THAN';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'CONTEXT','Trang phục trong không gian lễ hội','Các làng Quan họ xứ Kinh Bắc có sinh hoạt hát gắn với hội đình, hội chùa vào mùa xuân và mùa thu. Bộ trang phục liền chị cần được đọc trong mối liên hệ với cuộc hát, người đối đáp và cộng đồng làng, chứ không chỉ như một hình ảnh chụp riêng lẻ.','Cục Di sản văn hóa – Dân ca Quan họ Bắc Ninh','https://dsvh.gov.vn/dan-ca-quan-ho-bac-ninh-482' FROM outfits WHERE code='AO_TU_THAN';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'PRESERVATION','Giữ trang phục cùng thực hành văn hóa','Bảo tồn văn hóa Quan họ cần sự trao truyền của nghệ nhân và tiếp nối trong cộng đồng. Với trang phục lấy cảm hứng từ không gian này, nên ghi rõ bối cảnh sử dụng, đồng thời tìm hiểu lề lối hát và giao tiếp. Như vậy, câu chuyện văn hóa không bị thu gọn thành một bộ áo nhiều màu.','Cục Di sản văn hóa – Dân ca Quan họ Bắc Ninh','https://dsvh.gov.vn/dan-ca-quan-ho-bac-ninh-482' FROM outfits WHERE code='AO_TU_THAN';
UPDATE cultural_knowledge SET title='Từ Đàng Trong đến thời Nguyễn',content='Sở Văn hóa, Thể thao và Du lịch Huế gắn áo ngũ thân với quyết định về y phục của Nguyễn Phúc Khoát năm 1744 tại Đàng Trong. Đến thời Minh Mạng, áo được phổ biến rộng hơn trên cả nước và trở thành tiền thân quan trọng của áo dài hiện đại.',source_name='Sở Văn hóa, Thể thao và Du lịch thành phố Huế – Lễ đón nhận danh hiệu Di sản văn hóa phi vật thể quốc gia “Tri thức may, mặc Áo dài Huế”',source_url='https://svhttdl.hue.gov.vn/tin-trong-tinh/le-don-nhan-danh-hieu-di-san-van-hoa-phi-vat-the-quoc-gia-tri-thuc-may-mac-ao-dai-hue.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_NGU_THAN') AND category='ORIGIN';
UPDATE cultural_knowledge SET title='Năm thân, năm khuy và kỹ thuật may',content='Áo gồm hai thân trước, hai thân sau và thân con nằm bên trong, cùng năm khuy. Kiểu tay chẽn có ống tay gọn. Kỹ thuật may chú trọng ghép hoa văn khớp ở sống áo, đường chỉ nhỏ và đường cong chân tà; phom nam, nữ có khác biệt ở cổ, tay và độ dài.',source_name='Cổng du lịch Huế – Sở Văn hóa, Thể thao và Du lịch – Tinh tế áo dài ngũ thân',source_url='https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_NGU_THAN') AND category='CHARACTERISTICS';
UPDATE cultural_knowledge SET title='Cách diễn giải về gia đình và đạo lý',content='Theo Nguyễn Xuân Hoa, bốn thân chính được liên hệ với cha mẹ hai bên, thân con với người mặc. Năm khuy được diễn giải qua ngũ thường và ngũ luân. Đây là cách đọc biểu tượng trong bối cảnh đạo lý xưa, giúp hiểu trang phục mà không biến thành yêu cầu đạo đức áp đặt hôm nay.',source_name='Cổng du lịch Huế – Sở Văn hóa, Thể thao và Du lịch – Tinh tế áo dài ngũ thân',source_url='https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_NGU_THAN') AND category='MEANING';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'WEARING','Sự đồng bộ của khăn, áo và quần','Cách phối truyền thống được giới thiệu gồm khăn quấn đầu, áo lót trắng, áo ngũ thân và quần sáng màu, ống rộng. Việc phối đủ lớp giúp hiểu tổng thể hình dáng. Khi phục dựng, cần xem cả kết cấu áo và phụ kiện, thay vì chỉ mô phỏng hàng khuy hoặc chọn vải gấm.','Cổng du lịch Huế – Sở Văn hóa, Thể thao và Du lịch – Tinh tế áo dài ngũ thân','https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0' FROM outfits WHERE code='AO_NGU_THAN';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'CONTEXT','Áo ngũ thân trong câu chuyện áo dài Huế','Áo ngũ thân thuộc tiến trình lịch sử của áo dài Huế. Bài viết về di sản cho thấy tập quán mặc áo dài được nhiều thế hệ duy trì, từ học sinh tới người buôn bán. Điều này mở ra cách nhìn trang phục như thực hành sống, bên cạnh giá trị lịch sử của phom áo.','Sở Văn hóa, Thể thao và Du lịch thành phố Huế – Lễ đón nhận danh hiệu Di sản văn hóa phi vật thể quốc gia “Tri thức may, mặc Áo dài Huế”','https://svhttdl.hue.gov.vn/tin-trong-tinh/le-don-nhan-danh-hieu-di-san-van-hoa-phi-vat-the-quoc-gia-tri-thuc-may-mac-ao-dai-hue.html' FROM outfits WHERE code='AO_NGU_THAN';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'PRESERVATION','Gìn giữ tri thức may và mặc','Ngày 9/8/2024, tri thức may và mặc áo dài của người Huế được ghi danh di sản văn hóa phi vật thể quốc gia. Đối tượng được ghi nhận là tri thức, nghề và tập quán; không chỉ một chiếc áo. Bảo tồn vì thế cần hỗ trợ người làm nghề và nối việc may đo với thiết kế sáng tạo.

Thông tin ghi danh ở đây là cấp quốc gia.','Sở Văn hóa, Thể thao và Du lịch thành phố Huế – Lễ đón nhận danh hiệu Di sản văn hóa phi vật thể quốc gia “Tri thức may, mặc Áo dài Huế”','https://svhttdl.hue.gov.vn/tin-trong-tinh/le-don-nhan-danh-hieu-di-san-van-hoa-phi-vat-the-quoc-gia-tri-thuc-may-mac-ao-dai-hue.html' FROM outfits WHERE code='AO_NGU_THAN';
UPDATE cultural_knowledge SET title='Nhật Bình trong nội cung triều Nguyễn',content='Nguyễn Xuân Hoa ghi nhận quy định về Nhật Bình từ thời Gia Long. Áo là triều phục của một số bậc cung phi nhưng là thường phục của hoàng hậu, công chúa; công năng thay đổi theo địa vị người mặc.',source_name='Khám phá Huế – nghiên cứu của Nguyễn Xuân Hoa, nguồn Báo Thừa Thiên Huế – Giữ áo dài Nhật Bình cho Huế',source_url='https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28' WHERE outfit_id=(SELECT id FROM outfits WHERE code='NHAT_BINH') AND category='ORIGIN';
UPDATE cultural_knowledge SET title='Cổ chữ nhật, thân rộng và tay rộng',content='Nhật Bình có phần cổ bản rộng tạo khung chữ nhật trước ngực, mở giữa phía trước, thân và tay áo rộng. Tư liệu mô tả áo bốn thân, có khuy ở vùng ngực và hoa văn trang trí. Chính tổng thể cổ, tay, thân làm nên dấu hiệu nhận diện.',source_name='Khám phá Huế – nghiên cứu của Nguyễn Xuân Hoa, nguồn Báo Thừa Thiên Huế – Giữ áo dài Nhật Bình cho Huế',source_url='https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28' WHERE outfit_id=(SELECT id FROM outfits WHERE code='NHAT_BINH') AND category='CHARACTERISTICS';
UPDATE cultural_knowledge SET title='Trang phục và trật tự cung đình',content='Trong quy chế cũ, màu áo và đồ trang sức góp phần thể hiện phẩm cấp. Bởi vậy, cùng tên Nhật Bình không có nghĩa mọi người dùng một màu hay một bộ phụ kiện. Đọc trang phục cùng địa vị và hoàn cảnh lịch sử giúp hiểu vẻ trang trọng của áo.',source_name='Khám phá Huế – nghiên cứu của Nguyễn Xuân Hoa, nguồn Báo Thừa Thiên Huế – Giữ áo dài Nhật Bình cho Huế',source_url='https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28' WHERE outfit_id=(SELECT id FROM outfits WHERE code='NHAT_BINH') AND category='MEANING';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'WEARING','Khăn và đồ đội đầu qua các thời kỳ','Đồ đội đầu đi cùng Nhật Bình từng thay đổi trong triều Nguyễn; khăn vành được ghi nhận vào giai đoạn cuối triều. Khi dựng lại một bộ áo theo thời kỳ, cần đối chiếu cả áo lẫn đồ đội đầu, tránh coi cách phối cuối triều là chuẩn cho mọi giai đoạn.','Khám phá Huế – nghiên cứu của Nguyễn Xuân Hoa, nguồn Báo Thừa Thiên Huế – Giữ áo dài Nhật Bình cho Huế','https://khamphahue.com.vn/Du-lich/Chi-tiet/tid/Giu-ao-dai-Nhat-Binh-cho-Hue.html/pid/10926/cid/28' FROM outfits WHERE code='NHAT_BINH';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'CONTEXT','Trải nghiệm cổ phục trong đời sống hiện đại','Bài giới thiệu cổ phục Huế năm 2025 ghi nhận Nhật Bình được chọn cho ảnh cưới, lễ hội và trải nghiệm chụp ảnh. Việc mặc áo tại không gian di sản giúp người trẻ, du khách tiếp cận câu chuyện Huế. Bối cảnh hiện đại này có mục đích khác với quy chế nội cung xưa.','Khám phá Huế – Chụp hình với cổ phục Huế - Gìn giữ giá trị truyền thống trong nhịp sống hiện đại','https://khamphahue.com.vn/Hue-24h/Su-kien/pid/17822/cid/28?tid=Chup-hinh-voi-co-phuc-Hue-Gin-giu-gia-tri-truyen-thong-trong-nhip-song-hien-dai.html' FROM outfits WHERE code='NHAT_BINH';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'PRESERVATION','Phục dựng và thiết kế lấy cảm hứng','Sức hấp dẫn của cổ phục gắn với đường nét, chất liệu và kỹ thuật thủ công. Khi giới thiệu một bộ Nhật Bình hôm nay, nên nói rõ đó là mẫu phục dựng theo tư liệu hay thiết kế lấy cảm hứng.

Với bản sáng tạo, màu và chi tiết có thể được lựa chọn theo nhu cầu chụp ảnh; cần phân biệt lựa chọn ấy với mô tả lịch sử trong phần nguồn gốc.','Khám phá Huế – Chụp hình với cổ phục Huế - Gìn giữ giá trị truyền thống trong nhịp sống hiện đại','https://khamphahue.com.vn/Hue-24h/Su-kien/pid/17822/cid/28?tid=Chup-hinh-voi-co-phuc-Hue-Gin-giu-gia-tri-truyen-thong-trong-nhip-song-hien-dai.html' FROM outfits WHERE code='NHAT_BINH';
UPDATE cultural_knowledge SET title='Trang phục gắn với vùng sông nước Nam Bộ',content='Áo bà ba gắn bó với phụ nữ Nam Bộ, nhất là vùng miệt vườn, ruộng đồng Cửu Long. Bài nguồn nêu nhiều giả thuyết xuất xứ, nên không khẳng định một người sáng tạo hay niên đại duy nhất.',source_name='Ủy ban Nhà nước về người Việt Nam ở nước ngoài – Áo bà ba – Trang phục của phụ nữ Nam Bộ',source_url='https://scov.gov.vn/ban-sac-van-hoa/huong-vi-que-nha/ao-ba-ba-trang-phuc-cua-phu-nu-nam-bo.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_BA_BA') AND category='ORIGIN';
UPDATE cultural_knowledge SET title='Phom áo gọn và thuận tiện',content='Dạng cổ điển không cổ, lưng một mảnh, thân trước hai mảnh cài khuy giữa; áo xẻ hông và dài qua mông. Các biến thể cải tiến thêm cổ, màu và họa tiết. Vì vậy, nên phân biệt đặc điểm của dạng cổ điển với mẫu thời trang được thiết kế về sau.',source_name='Ủy ban Nhà nước về người Việt Nam ở nước ngoài – Áo bà ba – Trang phục của phụ nữ Nam Bộ',source_url='https://scov.gov.vn/ban-sac-van-hoa/huong-vi-que-nha/ao-ba-ba-trang-phuc-cua-phu-nu-nam-bo.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_BA_BA') AND category='CHARACTERISTICS';
UPDATE cultural_knowledge SET title='Nét mộc mạc từ sinh hoạt lao động',content='Áo bà ba thường gợi sự gần gũi của phụ nữ phương Nam. Màu nâu, đen từng phù hợp việc đi lại giữa sông rạch, bùn đất; chất vải dễ giặt, nhanh khô phục vụ lao động. Vẻ đẹp trang phục gắn với sự tiện dụng và đời sống thường ngày.',source_name='Ủy ban Nhà nước về người Việt Nam ở nước ngoài – Áo bà ba – Trang phục của phụ nữ Nam Bộ',source_url='https://scov.gov.vn/ban-sac-van-hoa/huong-vi-que-nha/ao-ba-ba-trang-phuc-cua-phu-nu-nam-bo.html' WHERE outfit_id=(SELECT id FROM outfits WHERE code='AO_BA_BA') AND category='MEANING';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'WEARING','Cách phối với quần và biến thể','Bộ bà ba cổ điển thường đi cùng quần đen dài. Màu áo nhẹ cũng được chọn khi đi chơi; các thiết kế sau này đa dạng hơn. Khi muốn thể hiện dáng truyền thống, hãy chú ý quan hệ giữa chiều dài áo, phần xẻ hông và quần đi cùng.','Ủy ban Nhà nước về người Việt Nam ở nước ngoài – Áo bà ba – Trang phục của phụ nữ Nam Bộ','https://scov.gov.vn/ban-sac-van-hoa/huong-vi-que-nha/ao-ba-ba-trang-phuc-cua-phu-nu-nam-bo.html' FROM outfits WHERE code='AO_BA_BA';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'CONTEXT','Từ sinh hoạt đến sự kiện văn hóa','Áo bà ba còn được dùng để kể câu chuyện địa phương. Bài đăng của Bộ Văn hóa, Thể thao và Du lịch tháng 6/2023 giới thiệu kế hoạch Festival Áo bà ba ở Hậu Giang, kết hợp hình ảnh trang phục với triển lãm, ẩm thực và trò chơi dân gian. Đây là một ví dụ về đưa trang phục vào hoạt động cộng đồng.','Bộ Văn hóa, Thể thao và Du lịch – Hậu Giang lần đầu tiên tổ chức Festival Áo bà ba','https://bvhttdl.gov.vn/hau-giang-lan-dau-tien-to-chuc-festival-ao-ba-ba-20230627111819393.htm' FROM outfits WHERE code='AO_BA_BA';
INSERT INTO cultural_knowledge(outfit_id,category,title,content,source_name,source_url) SELECT id,'PRESERVATION','Giữ câu chuyện đất và người','Ý tưởng sự kiện Hậu Giang năm 2023 nhấn mạnh bản sắc địa phương qua áo bà ba, thay vì chỉ trình diễn thời trang. Khi giới thiệu áo hôm nay, có thể kết nối với ký ức gia đình và môi trường sinh hoạt Nam Bộ.

Phần phối đồ của ứng dụng là gợi ý sáng tạo; người đọc có thể mở bài nguồn để phân biệt câu chuyện văn hóa với lựa chọn thiết kế hiện đại.','Bộ Văn hóa, Thể thao và Du lịch – Hậu Giang lần đầu tiên tổ chức Festival Áo bà ba','https://bvhttdl.gov.vn/hau-giang-lan-dau-tien-to-chuc-festival-ao-ba-ba-20230627111819393.htm' FROM outfits WHERE code='AO_BA_BA';
